javascript:(async()=>{let r=document.querySelector('div.relative.isolate.my-3.flex.flex-col');if(!r){const sb=document.querySelector('button[aria-label="Sources"]');if(!sb){alert('Bouton Sources introuvable. Ouvre une reponse ChatGPT avec recherche web ou trace visible.');return;}sb.click();const t0=Date.now();while(Date.now()-t0<6000){await new Promise(s=>setTimeout(s,150));r=document.querySelector('div.relative.isolate.my-3.flex.flex-col');if(r)break;}if(!r){alert('Le panneau visible n a pas pu etre charge apres 6s.');return;}}for(let i=0;i<5;i++){const b=[...r.querySelectorAll('button')].filter(x=>/\d+\s*more/i.test(x.innerText));if(!b.length)break;b.forEach(x=>x.click());await new Promise(s=>setTimeout(s,300));}const cleanStep=s=>{const links=[...s.querySelectorAll('a[href]')].map(a=>a.href);const linkTexts=new Set([...s.querySelectorAll('a[href]')].map(a=>a.innerText.trim()));const lines=s.innerText.split('\n');const title=(lines[0]||'').trim();const body=lines.slice(1).map(l=>l.trim()).filter(l=>l.length>0).filter(l=>!linkTexts.has(l)).filter(l=>!/^show\s+(less|more)$/i.test(l)).filter(l=>!/^\d+\s+more$/i.test(l)).join('\n');return{title,body,sources:links};};const steps=[...r.children].map(cleanStep).filter(st=>!/^thought for \d+/i.test(st.title)&&!(st.title.toLowerCase()==='done'));const all=[...new Set(steps.flatMap(s=>s.sources))];const head='# Trace visible ChatGPT et sources\n\nURL: '+location.href+'\nDate: '+new Date().toISOString()+'\n\n';const buildFull=()=>{let m=head;steps.forEach((st,i)=>{m+='## Etape '+(i+1)+' — '+st.title+'\n\n';if(st.body)m+=st.body+'\n\n';if(st.sources.length){m+='**Sources :**\n';st.sources.forEach(u=>m+='- '+u+'\n');m+='\n';}});m+='\n---\n\n# Toutes les sources ('+all.length+')\n\n';all.forEach(u=>m+='- '+u+'\n');return m;};const buildSourcesOnly=()=>{let m='# Sources ChatGPT\n\nURL: '+location.href+'\nDate: '+new Date().toISOString()+'\n\nTotal: '+all.length+' sources uniques\n\n';all.forEach(u=>m+='- '+u+'\n');return m;};let mode='full';let md=buildFull();document.getElementById('__cgpt_extract_modal__')?.remove();const ov=document.createElement('div');ov.id='__cgpt_extract_modal__';ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:2147483647;display:flex;align-items:center;justify-content:center;font-family:system-ui,sans-serif';const bx=document.createElement('div');bx.style.cssText='background:#fff;color:#111;width:min(900px,92vw);height:min(80vh,720px);border-radius:12px;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.3);overflow:hidden';bx.innerHTML='<div style="padding:12px 16px;border-bottom:1px solid #e5e5e5;display:flex;align-items:center;gap:8px;flex-wrap:wrap"><strong style="flex:1;min-width:200px">Export visible ChatGPT — '+steps.length+' etapes / '+all.length+' sources</strong><div style="display:inline-flex;border:1px solid #d1d5db;border-radius:6px;overflow:hidden"><button id="__cgpt_full__" style="padding:6px 10px;border:0;background:#2563eb;color:#fff;cursor:pointer;font-size:12px">Trace visible + sources</button><button id="__cgpt_only__" style="padding:6px 10px;border:0;background:#f9fafb;color:#111;cursor:pointer;font-size:12px;border-left:1px solid #d1d5db">Sources uniquement</button></div><button id="__cgpt_copy__" style="padding:6px 12px;border:1px solid #d1d5db;background:#f9fafb;border-radius:6px;cursor:pointer">Copier</button><button id="__cgpt_dl__" style="padding:6px 12px;border:1px solid #d1d5db;background:#f9fafb;border-radius:6px;cursor:pointer">.md</button><button id="__cgpt_close__" style="padding:6px 10px;border:1px solid #d1d5db;background:#f9fafb;border-radius:6px;cursor:pointer">✕</button></div><textarea id="__cgpt_ta__" style="flex:1;width:100%;border:0;outline:0;padding:14px 16px;font:13px ui-monospace,Menlo,Consolas,monospace;resize:none;white-space:pre;background:#fafafa"></textarea>';ov.appendChild(bx);document.body.appendChild(ov);const ta=document.getElementById('__cgpt_ta__');ta.value=md;const fb=document.getElementById('__cgpt_full__');const ob=document.getElementById('__cgpt_only__');const setMode=m=>{mode=m;md=m==='full'?buildFull():buildSourcesOnly();ta.value=md;if(m==='full'){fb.style.background='#2563eb';fb.style.color='#fff';ob.style.background='#f9fafb';ob.style.color='#111';}else{ob.style.background='#2563eb';ob.style.color='#fff';fb.style.background='#f9fafb';fb.style.color='#111';}};fb.onclick=()=>setMode('full');ob.onclick=()=>setMode('only');document.getElementById('__cgpt_close__').onclick=()=>ov.remove();ov.addEventListener('click',e=>{if(e.target===ov)ov.remove();});document.getElementById('__cgpt_copy__').onclick=async()=>{try{await navigator.clipboard.writeText(md);document.getElementById('__cgpt_copy__').textContent='Copie';}catch(e){ta.select();document.execCommand('copy');document.getElementById('__cgpt_copy__').textContent='Copie';}};document.getElementById('__cgpt_dl__').onclick=()=>{const b=new Blob([md],{type:'text/markdown'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=(mode==='full'?'chatgpt-visible-trace-':'chatgpt-sources-')+Date.now()+'.md';a.click();};})();
